// Match with the audited balance sheet (owner, 29-Oct-2026: "match the figures uploaded ... and generated by FinCom,
// identify the difference and make it correct as per balance uploaded"), on the Checks tab. The audited balance sheet as at
// the year's end is uploaded here (or as next year's "last year's balance sheet": the same store, FinPyBs, fy + 1). FinRecon
// (src/js/88-fin-recon.js) compares it head by head and note line by note line, each FinCom figure opening its ledgers in
// the trial balance; then proposes, in order, mapping changes and audit entries (FinCom's own adjustments dated the balance
// sheet date, never posted to Tally), and says how much of the profit's difference they explain and what is left. Each
// proposal: Accept / Reject (or all of a kind); each change recorded (who, when) and undone from the history. The accepted
// entries go into next year's opening balances until they are passed in Tally; "Download journal entries for Tally".
import { useState } from "react";
import Button from "../../../parts/Button.jsx";
import { rs } from "./util.js";
import { openTb } from "./Sheets.jsx";
import { readFile, Lines } from "./PyBs.jsx";
import AiMapSlot, { earlierMapping } from "./aimapSlot.jsx";

const D2 = (iso) => { try { return fmtDate(String(iso).slice(0, 10)); } catch (e) { return String(iso).slice(0, 10); } };
const codesOfKey = (k) => { const z = FinSt.PPE.concat(FinSt.INT).find((p) => p[2] === k); return z ? [z[2], z[3]].filter(Boolean) : k === "4A" ? ["4A", "4E"] : [k]; };

function Upload({ fy, kind, label }) {
  const [draft, setDraft] = useState(null), [busy, setBusy] = useState(false), [err, setErr] = useState("");
  const ny = String(+fy + 1);
  const pick = async (ev) => {
    const file = ev.target.files && ev.target.files[0]; ev.target.value = ""; if (!file) return;
    setBusy(true); setErr(""); setDraft(null);
    try { const r = await readFile(file, kind); r.usePy = true; setDraft(r); } catch (e) { setErr((e && e.message) || String(e)); } finally { setBusy(false); }
  };
  const line = (i, patch) => { const ls = draft.lines.slice(); ls[i] = Object.assign({}, ls[i], patch); setDraft(Object.assign({}, draft, { lines: ls })); };
  return <>
    <label className={"btn small" + (busy ? " disabled" : "")} data-fin-recon-up="">{busy ? "Reading…" : label}
      <input type="file" accept=".xlsx,.xls,.csv,.pdf,application/pdf" data-fin-recon-file="" disabled={busy} onChange={pick} style={{ display: "none" }} /></label>
    {err && <p className="bk-alert" data-fin-recon-err="">{err}</p>}
    {draft && <div className="fin-pybs-confirm" data-fin-recon-confirm="">
      <p className="note">{"Read from " + draft.file + ": check each line’s code and figure, then keep it. It is also next year’s “last year’s balance sheet”."}</p>
      <Lines lines={draft.lines} kind={kind} edit onLine={line} />
      <div className="fin-pybs-act"><Button className="btn small primary" data-fin-recon-save="" onClick={() => { const k = FinPyBs.save(ny, Object.assign({}, draft, { confirmed: true })); setDraft(null); toast("The audited balance sheet is kept (version " + k.v + ")."); render(); }}>Keep it</Button>
        <Button className="btn small" onClick={() => setDraft(null)}>Cancel</Button></div>
    </div>}
  </>;
}

export default function Recon({ d, fy }) {
  const [open, setOpen] = useState({});
  if (!d.period || !d.period.full) return null;
  const kind = d.kind, asAt = FinSt.DMY(String(+fy + 1) + "0331");
  const p = FinRecon.propose(fy), log = FinRecon.log(fy), inTally = FinRecon.inTally(fy), jr = FinRecon.journal(fy);
  const act = (f, msg) => { f(); toast(msg); render(); };
  const by = { by: undefined };
  return <div className="fin-recon" data-fin-recon="">
    <h4>{"Match with the audited balance sheet as at " + asAt}</h4>
    {p.none ? <><p className="note">Upload the audited balance sheet for this year: FinCom compares it with its own, head by head, and proposes how to make them agree. Read here, never sent anywhere.</p>
      <Upload fy={fy} kind={kind} label={"Upload the audited balance sheet as at " + asAt + " (Excel or PDF)"} /></>
      : p.error ? <p className="bk-alert">{p.error}</p> : <>
        <div className="fin-pybs-head"><p className="note" data-fin-recon-state="">{(p.bad ? p.bad + " head" + (p.bad > 1 ? "s differ" : " differs") : "Every head agrees") + " · in rupees"}</p>
          <Upload fy={fy} kind={kind} label="Upload another version" /></div>
        <div className="fin-box"><table className="fin-t" data-statement="" data-fin-table="recon"><colgroup><col /><col className="fig" /><col className="fig" /><col className="fig" /></colgroup>
          <thead><tr><th>Head / note line</th><th className="n">Audited</th><th className="n">FinCom</th><th className="n">Difference</th></tr></thead>
          <tbody>{p.heads.map((h) => [
            <tr key={h.id} className="sub" data-fin-rhead={h.id} data-v={h.diff}><td><button type="button" className="fin-fig" aria-expanded={!!open[h.id]} onClick={() => setOpen(Object.assign({}, open, { [h.id]: !open[h.id] }))}>{(open[h.id] ? "▾ " : "▸ ") + h.label}</button></td>
              <td className="n">{rs(h.aud)}</td><td className="n">{rs(h.fin)}</td><td className={"n " + (h.diff ? "fin-bad" : "fin-ok")}>{h.diff ? rs(h.diff) : "0"}</td></tr>,
            ...(open[h.id] ? h.codes.map((z) => <tr key={h.id + z.key} className="l1" data-fin-rcode={z.key} data-v={z.diff}><td>{z.key + " " + z.label}</td><td className="n">{rs(z.aud)}</td>
              <td className="n"><button type="button" className="fin-fig" title="Open its ledgers in the trial balance" data-fin-rled={z.key} onClick={() => openTb(codesOfKey(z.key), "Audited balance sheet · " + z.label)}>{rs(z.fin)}</button></td>
              <td className={"n " + (z.diff ? "fin-bad" : "")}>{z.diff ? rs(z.diff) : "0"}</td></tr>) : [])])}</tbody></table></div>
        {!earlierMapping(fy) && <AiMapSlot d={d} fy={fy} mode="close" />}

        {p.mapping.length > 0 && <div className="fin-rprops" data-fin-rmaps="">
          <div className="fin-rph"><b>{"Mapping changes (" + p.mapping.length + ")"}</b><Button className="btn small" data-fin-acceptall="map" onClick={() => act(() => FinRecon.acceptAll(fy, "map", by), "Mapping changes accepted.")}>Accept all mapping changes</Button></div>
          {p.mapping.map((m) => <div key={m.id} className="fin-rprop" data-fin-prop={m.id}><div><b>{m.ledger}</b>{": " + m.from + " " + FinSt.CODES[m.from].label + " → " + m.to + " " + FinSt.CODES[m.to].label + " · " + rs(m.amount)}
            <span className="fin-why">{m.why + (m.hand ? " (its code was chosen by hand)" : "")}</span></div>
            <span className="fin-ract"><Button className="btn small" data-fin-accept={m.id} onClick={() => act(() => FinRecon.accept(fy, m.id, by), m.ledger + ": " + m.to + ", accepted.")}>Accept</Button>
              <Button className="btn small" data-fin-reject={m.id} onClick={() => act(() => FinRecon.reject(fy, m.id, by), "Rejected.")}>Reject</Button></span></div>)}
        </div>}
        {p.adjustments.length > 0 && <div className="fin-rprops" data-fin-radjs="">
          <div className="fin-rph"><b>{"Adjustments, dated " + asAt + " (" + p.adjustments.length + ")"}</b><Button className="btn small" data-fin-acceptall="adj" onClick={() => act(() => FinRecon.acceptAll(fy, "adj", by), "Adjustments accepted: in FinCom only, never posted to Tally.")}>Accept all adjustments</Button></div>
          {p.adjustments.map((a) => <div key={a.id} className="fin-rprop" data-fin-prop={a.id}><div>{"Dr " + a.dr + " / Cr " + a.cr + " · " + rs(a.amt)}<span className="fin-why">{a.narr}</span></div>
            <span className="fin-ract"><Button className="btn small" data-fin-accept={a.id} onClick={() => act(() => FinRecon.accept(fy, a.id, by), "Adjustment accepted (FinCom only).")}>Accept</Button>
              <Button className="btn small" data-fin-reject={a.id} onClick={() => act(() => FinRecon.reject(fy, a.id, by), "Rejected.")}>Reject</Button></span></div>)}
        </div>}
        {p.profit && p.profit.diff !== 0 && <p className="note" data-fin-rprofit="">{p.profit.head + " differ" + " by " + rs(p.profit.diff) + ": the adjustments proposed explain " + rs(p.profit.explained) + (p.profit.left ? "; " + rs(p.profit.left) + " is not explained." : "; nothing is left.")}</p>}
        {p.left.length ? <div className="fin-rleft" data-fin-rleft=""><b>{p.mapping.length || p.adjustments.length ? "Left once these are accepted (not explained, left as they are):" : "Not explained (left as they are):"}</b>
          <ul>{p.left.map((z) => <li key={z.id} data-fin-left={z.id}>{z.label + ": " + rs(z.diff)}</li>)}</ul></div>
          : p.bad ? <p className="fin-ok" data-fin-rleft="">Once these are accepted, every head agrees.</p> : null}
        {p.rejected.length > 0 && <p className="note" data-fin-rrejected="">{p.rejected.length + " rejected: see the history to take one back."}</p>}

        {log.length > 0 && <details className="fin-rlog" data-fin-rlog=""><summary>{"History (" + log.length + ")"}</summary>
          <ul>{log.slice().reverse().map((e) => <li key={e.id} data-fin-logid={e.id}>{(e.kind === "accept" ? "Accepted: " : e.kind === "reject" ? "Rejected: " : "") + e.what + " · " + e.by + ", " + D2(e.at) + (e.undone ? " · undone by " + e.undone.by + ", " + D2(e.undone.at) : "")}
            {!e.undone && e.kind !== "tally" && <button type="button" className="linkbtn" data-fin-undo={e.id} onClick={() => act(() => FinRecon.undo(fy, e.id, by), "Undone.")}>{e.kind === "reject" ? "Take back" : "Undo"}</button>}</li>)}</ul></details>}
        {jr.length > 0 && <div className="fin-rcarry" data-fin-rcarry="">
          <p className="note">{jr.length + " accepted entr" + (jr.length > 1 ? "ies" : "y") + " dated " + asAt + (inTally ? ": passed in Tally, so FinCom no longer adds them." : ": in FinCom only, and in " + (+fy + 1) + "-" + String(+fy + 2).slice(2) + "’s opening balances until they are passed in Tally.")}</p>
          <Button className="btn small" data-fin-journal="" onClick={() => window.loadFinExport().then((m) => m.FinXlsx.journal(fy)).catch((e) => toast(e && (e.finLoad || e.code === "lib_missing") ? "Excel is being prepared: try again in a moment" : "Could not make the file: " + ((e && e.message) || e)))}>Download journal entries for Tally</Button>
          <label className="note"><input type="checkbox" data-fin-intally="" checked={inTally} onChange={(ev) => act(() => FinRecon.setInTally(fy, ev.target.checked, by), ev.target.checked ? "FinCom stops adding them: Tally has them." : "FinCom adds them again.")} /> I have passed these entries in Tally</label>
        </div>}
      </>}
  </div>;
}
